code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A horizontal run of 5 marks a width; the column attached below/above
    # its endpoint supplies the colors for the rows to spread across it.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] == 5:
                c += 1
            b = c - 1
            for anchor in (a, b):
                for dr in (1, -1):
                    rr = r + dr
                    if not (0 <= rr < h) or grid[rr][anchor] in (0, 5):
                        continue
                    vals = []
                    while 0 <= rr < h and grid[rr][anchor] not in (0, 5):
                        vals.append((rr, grid[rr][anchor]))
                        rr += dr
                    for sr, color in vals:
                        for cc in range(a, b + 1):
                            if out[sr][cc] == 0:
                                out[sr][cc] = color
                    break

    # A vertical run of 5 marks a height; a colored strip beside its end
    # is repeated upward/downward along the run.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and grid[r][c] == 5:
                r += 1
            b = r - 1
            for side in (1, -1):
                sc = c + side
                if not (0 <= sc < w):
                    continue
                # Find the contiguous colored rows touching the end of the bar.
                end = None
                for er in (b, a):
                    if grid[er][sc] not in (0, 5):
                        end = er
                        break
                if end is None:
                    continue
                top = end
                while top - 1 >= a and grid[top - 1][sc] not in (0, 5):
                    top -= 1
                bottom = end
                while bottom + 1 <= b and grid[bottom + 1][sc] not in (0, 5):
                    bottom += 1
                source = [grid[rr][sc:w] if side == 1 else grid[rr][0:c] for rr in range(top, bottom + 1)]
                # Trim source strip to the contiguous nonzero region next to the guide.
                if side == 1:
                    width = 0
                    while c + 1 + width < w and any(grid[rr][c + 1 + width] not in (0, 5) for rr in range(top, bottom + 1)):
                        width += 1
                    src = [[grid[rr][c+1:c+1+width][j] for j in range(width)] for rr in range(top, bottom+1)]
                else:
                    left = c
                    while left - 1 >= 0 and any(grid[rr][left-1] not in (0,5) for rr in range(top,bottom+1)):
                        left -= 1
                    src = [grid[rr][left:c] for rr in range(top,bottom+1)]
                if not src or not src[0]:
                    continue
                for rr in range(a, b + 1):
                    pattern = src[(rr - a) % len(src)]
                    for j, color in enumerate(pattern):
                        cc = c + 1 + j if side == 1 else c - len(pattern) + j
                        if 0 <= cc < w and out[rr][cc] == 0:
                            out[rr][cc] = color
                break
    return out
